1	package tracepath
2	
3	import (
4		"sort"
5		"time"
6	)
7	
8	// Service implements the TracePath contract on top of a Store. It owns span
9	// ingestion, trace reassembly, critical path analysis, error propagation
10	// marking and the service dependency graph.
11	type Service struct {
12		store *Store
13		clock func() time.Time
14	}
15	
16	// NewService wires a store and an injectable clock.
17	func NewService(store *Store, clock func() time.Time) (*Service, error) {
18		if store == nil {
19			return nil, InternalError("service requires a store")
20		}
21		if clock == nil {
22			clock = time.Now
23		}
24		return &Service{store: store, clock: clock}, nil
25	}
26	
27	func (s *Service) now() string {
28		return s.clock().UTC().Format(idLayout)
29	}
30	
31	// runIdempotent executes action at most once per key. The first response is
32	// re-rendered from committed state for every later request that carries the
33	// same key and the same resource identity, so a replay is byte-identical by
34	// construction. Reusing a key for another operation, or for another resource,
35	// is a conflict.
36	func (s *Service) runIdempotent(key string, operation string, identity string, action func(state *State) (any, error)) (any, error) {
37		if key == "" {
38			return nil, ValidationError("Idempotency-Key header is required")
39		}
40		if len(key) > 200 {
41			return nil, ValidationError("Idempotency-Key must be at most 200 characters")
42		}
43		var response any
44		err := s.store.Update(func(state *State) error {
45			if record, found := state.Idempotency[key]; found {
46				if record.Operation != operation {
47					return ConflictError("idempotency key was already used for another operation")
48				}
49				if record.Identity != identity {
50					return ConflictError("idempotency key was already used for resource %s", record.Identity)
51				}
52				response = identity
53				return nil
54			}
55			value, err := action(state)
56			if err != nil {
57				return err
58			}
59			state.Idempotency[key] = &IdempotencyRecord{
60				Key:       key,
61				Operation: operation,
62				Identity:  identity,
63				CreatedAt: s.now(),
64			}
65			response = value
66			return nil
67		})
68		if err != nil {
69			return nil, err
70		}
71		return response, nil
72	}
73	
74	// spanResponse is the public projection of one ingested span.
75	type spanResponse struct {
76		TraceID    string            `json:"trace_id"`
77		SpanID     string            `json:"span_id"`
78		ParentID   *string           `json:"parent_id"`
79		Service    string            `json:"service"`
80		Operation  string            `json:"operation"`
81		Kind       string            `json:"kind"`
82		StartTime  string            `json:"start_time"`
83		DurationNS int64             `json:"duration_ns"`
84		Status     string            `json:"status"`
85		Attributes map[string]string `json:"attributes"`
86		Accepted   bool              `json:"accepted"`
87		SpanCount  int               `json:"span_count"`
88		Complete   bool              `json:"complete"`
89		Valid      bool              `json:"valid"`
90		Violations []Validation      `json:"violations"`
91	}
92	
93	// renderSpan projects one stored span onto its public projection. The identity
94	// of the projected span is returned as well.
95	func renderSpan(state *State, traceID string, spanID string) (any, error) {
96		spans, found := state.Spans[traceID]
97		if !found {
98			return nil, InternalError("trace %s disappeared during ingestion", traceID)
99		}
100		span, found := spans[spanID]
101		if !found {
102			return nil, InternalError("span %s of trace %s disappeared during ingestion", spanID, traceID)
103		}
104		trace := assembleTrace(traceID, spans)
105		declared := trace.SpanCount
106		if trace.RootSpanCount != 0 {
107			declared = trace.RootSpanCount
108		}
109		response := &spanResponse{
110			TraceID:    span.TraceID,
111			SpanID:     span.SpanID,
112			ParentID:   span.ParentID,
113			Service:    span.Service,
114			Operation:  span.Operation,
115			Kind:       span.Kind,
116			StartTime:  span.StartTime,
117			DurationNS: span.DurationNS,
118			Status:     span.Status,
119			Attributes: map[string]string{},
120			Accepted:   true,
121			SpanCount:  declared,
122			Complete:   trace.Complete,
123			Valid:      trace.Valid,
124			Violations: publicViolations(trace.Violations),
125		}
126		for attribute, value := range span.Attributes {
127			response.Attributes[attribute] = value
128		}
129		return response, nil
130	}
131	
132	// IngestSpan validates and stores one span. Every check that needs the other
133	// spans of the trace (parent existence, trace id agreement, time containment)
134	// runs against the committed state under the store lock.
135	func (s *Service) IngestSpan(body []byte, key string) (any, error) {
136		var input SpanInput
137		if err := decodeObject(body, &input); err != nil {
138			return nil, err
139		}
140		start, err := validateSpanInput(&input)
141		if err != nil {
142			return nil, err
143		}
144		spanID, err := validateIdentifier(input.SpanID, "span_id")
145		if err != nil {
146			return nil, err
147		}
148		traceID, err := validateIdentifier(input.TraceID, "trace_id")
149		if err != nil {
150			return nil, err
151		}
152		operation := "ingest-span"
153		identity := traceID + "/" + spanID
154	
155		if _, err := s.runIdempotent(key, operation, identity, func(state *State) (any, error) {
156			spans, found := state.Spans[traceID]
157			if !found {
158				if parentID := input.ParentID; parentID != nil {
159					if _, elsewhere := findSpan(state, *parentID); elsewhere != nil {
160						return nil, ConflictError("span %s belongs to trace %s but its parent %s belongs to trace %s",
161							spanID, traceID, *parentID, *elsewhere)
162					}
163				}
164				spans = map[string]*SpanInput{}
165				state.Spans[traceID] = spans
166			}
167			if _, duplicate := spans[spanID]; duplicate {
168				return nil, ConflictError("span %s already exists in trace %s", spanID, traceID)
169			}
170			resolved, err := lineOf(spans, &input)
171			if err != nil {
172				return nil, err
173			}
174			if resolved != traceID {
175				return nil, ConflictError("span %s belongs to trace %s but its parent chain resolves to trace %s",
176					spanID, traceID, resolved)
177			}
178			if input.ParentID != nil {
179				parent, found := spans[*input.ParentID]
180				if found {
181					parentStart, _ := parseTime(parent.StartTime, "start_time")
182					parentEnd := parentStart.Add(time.Duration(parent.DurationNS))
183					end := start.Add(time.Duration(input.DurationNS))
184					if start.Before(parentStart) || end.After(parentEnd) {
185						return nil, ConflictError("span %s runs from %s to %s which is not contained in parent %s from %s to %s",
186							spanID, formatTime(start), formatTime(end), parent.SpanID, parent.StartTime, formatTime(parentEnd))
187					}
188				}
189			}
190			clone := input
191			clone.Attributes = map[string]string{}
192			for attribute, value := range input.Attributes {
193				clone.Attributes[attribute] = value
194			}
195			spans[spanID] = &clone
196			return nil, nil
197		}); err != nil {
198			return nil, err
199		}
200		return s.store.View(func(state *State) (any, error) {
201			return renderSpan(state, traceID, spanID)
202		})
203	}
204	
205	// findSpan locates a span id in any trace and returns its trace id.
206	func findSpan(state *State, spanID string) (*SpanInput, *string) {
207		for traceID, spans := range state.Spans {
208			if span, found := spans[spanID]; found {
209				id := traceID
210				return span, &id
211			}
212		}
213		return nil, nil
214	}
215	
216	func publicViolations(violations []Violation) []Validation {
217		public := make([]Validation, 0, len(violations))
218		for _, violation := range violations {
219			public = append(public, Validation{
220				Code:    violation.Code,
221				TraceID: violation.TraceID,
222				SpanID:  violation.SpanID,
223				Message: violation.Message,
224			})
225		}
226		return public
227	}
228	
229	// GetTrace reassembles one trace and fails when it is incomplete or unusable.
230	func (s *Service) GetTrace(traceID string) (any, error) {
231		value, err := s.store.View(func(state *State) (any, error) {
232			spans, found := state.Spans[traceID]
233			if !found {
234				return nil, NotFoundError("trace %s does not exist", traceID)
235			}
236			return assembleTrace(traceID, spans), nil
237		})
238		if err != nil {
239			return nil, err
240		}
241		trace := value.(*Trace)
242		if !trace.Complete {
243			return nil, InvalidTraceError(traceID, append([]Violation{{
244				Code:    "trace_incomplete",
245				TraceID: traceID,
246				SpanID:  "",
247				Message: "trace is not complete yet or its declared span_count does not match the ingested spans",
248			}}, trace.Violations...))
249		}
250		if !trace.Valid {
251			return nil, InvalidTraceError(traceID, trace.Violations)
252		}
253		return trace, nil
254	}
255	
256	// ListTraces summarises every stored trace with at least one span.
257	func (s *Service) ListTraces(service string, limit int) (any, error) {
258		if limit < 1 || limit > 400 {
259			return nil, ValidationError("limit must be between 1 and 400")
260		}
261		value, err := s.store.View(func(state *State) (any, error) {
262			summaries := []*TraceSummary{}
263			for _, traceID := range state.traceIDs() {
264				trace := assembleTrace(traceID, state.Spans[traceID])
265				if service != "" {
266					found := false
267					for _, node := range trace.Spans {
268						if node.Service == service {
269							found = true
270							break
271						}
272					}
273					if !found {
274						continue
275					}
276				}
277				summary := &TraceSummary{
278					TraceID:      trace.TraceID,
279					StartTime:    "",
280					DurationNS:   trace.DurationNS,
281					SpanCount:    trace.SpanCount,
282					ServiceCount: trace.ServiceCount,
283					ErrorSpans:   trace.ErrorSpans,
284					Complete:     trace.Complete,
285					Valid:        trace.Valid,
286				}
287				if trace.Root != nil {
288					rootID := trace.Root.SpanID
289					rootService := trace.Root.Service
290					summary.RootSpanID = &rootID
291					summary.RootService = &rootService
292					summary.StartTime = trace.Root.StartTime
293				}
294				summaries = append(summaries, summary)
295			}
296			sort.Slice(summaries, func(i, j int) bool {
297				left, _ := parseTime(summaries[i].StartTime, "start_time")
298				right, _ := parseTime(summaries[j].StartTime, "start_time")
299				if !left.Equal(right) {
300					return left.After(right)
301				}
302				return summaries[i].TraceID < summaries[j].TraceID
303			})
304			if len(summaries) > limit {
305				summaries = summaries[:limit]
306			}
307			return map[string]any{"traces": summaries}, nil
308		})
309		if err != nil {
310			return nil, err
311		}
312		return value, nil
313	}
314	
315	// CriticalPath walks the root-to-leaf path with the largest total self_time. It
316	// therefore needs time containment to hold, exactly like the invariant
317	// "critical path length equals the root span duration" does.
318	func (s *Service) CriticalPath(traceID string) (any, error) {
319		value, err := s.store.View(func(state *State) (any, error) {
320			spans, found := state.Spans[traceID]
321			if !found {
322				return nil, NotFoundError("trace %s does not exist", traceID)
323			}
324			return assembleTrace(traceID, spans), nil
325		})
326		if err != nil {
327			return nil, err
328		}
329		trace := value.(*Trace)
330		path := &CriticalPath{
331			TraceID:         traceID,
332			Method:          "longest chain below the root, weighted by self_time_ns; ties are broken by the longest sub-chain and then by the smallest span id sequence",
333			TraceDurationNS: trace.DurationNS,
334			Path:            []PathStep{},
335			Complete:        trace.Complete,
336			Valid:           trace.Valid || trace.Root == nil,
337			Violations:      publicViolations(trace.Violations),
338		}
339		if !trace.Complete {
340			path.Valid = false
341		}
342		if trace.Root == nil {
343			return path, nil
344		}
345		_, steps := longestSelfTimePath(trace.Root)
346		path.Path = steps
347		for _, step := range steps {
348			path.LengthNS += step.SelfTimeNS
349		}
350		return path, nil
351	}
352	
353	type pathCandidate struct {
354		// weight is the sum of self_time along the candidate: the value the response
355		// reports as the length of the path.
356		weight int64
357		// path is the longest self_time-weighted path of the subtree, used to break a
358		// tie between two branches that weigh the same.
359		path  int64
360		steps int
361		ids   []string
362	}
363	
364	// better ranks two candidates of the same node. More self_time wins. An equal
365	// weight is settled by the branch with the longer critical path, then by the
366	// shorter path, then by the lexicographically smallest span id sequence, so the
367	// output is deterministic.
368	func better(candidate pathCandidate, incumbent pathCandidate) bool {
369		if candidate.weight != incumbent.weight {
370			return candidate.weight > incumbent.weight
371		}
372		if candidate.path != incumbent.path {
373			return candidate.path > incumbent.path
374		}
375		if candidate.steps != incumbent.steps {
376			return candidate.steps < incumbent.steps
377		}
378		for index := 0; index < len(candidate.ids) && index < len(incumbent.ids); index++ {
379			if candidate.ids[index] != incumbent.ids[index] {
380				return candidate.ids[index] < incumbent.ids[index]
381			}
382		}
383		return len(candidate.ids) < len(incumbent.ids)
384	}
385	
386	// longestSelfTimePath returns the winning candidate of the subtree together
387	// with the steps of the critical path, both in pre-order. The tree builder has
388	// already computed maxPath for every span, so the winner is the child whose
389	// maxPath is the largest and the weight of the result is this node's maxPath.
390	func longestSelfTimePath(node *TraceNode) (pathCandidate, []PathStep) {
391		self := PathStep{
392			SpanID:     node.SpanID,
393			ParentID:   node.ParentID,
394			Service:    node.Service,
395			Operation:  node.Operation,
396			Depth:      node.Depth,
397			SelfTimeNS: node.SelfTimeNS,
398			StartTime:  node.StartTime,
399			EndTime:    node.EndTime,
400		}
401		best := pathCandidate{weight: node.SelfTimeNS, path: node.maxPath, steps: 1, ids: []string{node.SpanID}}
402		var bestSteps []PathStep
403		for _, child := range node.Children {
404			candidate, steps := longestSelfTimePath(child)
405			candidate.weight += node.SelfTimeNS
406			candidate.steps++
407			candidate.ids = append([]string{node.SpanID}, candidate.ids...)
408			if bestSteps == nil || better(candidate, best) {
409				best = candidate
410				bestSteps = steps
411			}
412		}
413		if bestSteps == nil {
414			bestSteps = []PathStep{}
415		}
416		steps := append([]PathStep{self}, bestSteps...)
417		weight := int64(0)
418		for _, item := range steps {
419			weight += item.SelfTimeNS
420		}
421		best.weight = weight
422		if best.weight < node.maxPath {
423			best.weight = node.maxPath
424		}
425		return best, steps
426	}
427	
428	// ServiceGraph aggregates the caller/callee graph. traceID limits the analysis
429	// to one trace; an empty traceID covers every stored trace.
430	func (s *Service) ServiceGraph(traceID string) (any, error) {
431		value, err := s.store.View(func(state *State) (any, error) {
432			graph := &ServiceGraph{
433				Services: []*ServiceStat{},
434				Edges:    []*ServiceEdge{},
435				Stats:    &GraphStats{},
436			}
437			ids := state.traceIDs()
438			if traceID != "" {
439				if _, found := state.Spans[traceID]; !found {
440					return nil, NotFoundError("trace %s does not exist", traceID)
441				}
442				ids = []string{traceID}
443				// The response always echoes an explicitly requested trace.
444				graph.TraceID = &ids[0]
445			}
446			services := map[string]*ServiceStat{}
447			edges := map[string]*ServiceEdge{}
448			graph.Stats.durations = []int64{}
449			for _, id := range ids {
450				trace := assembleTrace(id, state.Spans[id])
451				usable := trace.Valid && trace.Complete && trace.Root != nil
452				if !usable {
453					if traceID != "" {
454						// An explicitly requested trace is reported as-is, complete
455						// or not.
456						graph.Stats.PartialTraces = 1
457						return graph, nil
458					}
459					graph.Stats.PartialTraces++
460					continue
461				}
462				graph.Stats.TraceCount++
463				graph.Stats.SpanCount += trace.SpanCount
464				graph.Stats.ErrorSpans += trace.ErrorSpans
465				graph.Stats.durations = append(graph.Stats.durations, trace.DurationNS)
466				for _, node := range trace.Spans {
467					stat := services[node.Service]
468					if stat == nil {
469						stat = &ServiceStat{Service: node.Service, Operations: []*OperationStat{}, durations: []int64{}}
470						services[node.Service] = stat
471					}
472					stat.SpanCount++
473					stat.SelfTimeNS += node.SelfTimeNS
474					stat.durations = append(stat.durations, node.DurationNS)
475					if node.Error {
476						stat.ErrorSpans++
477					}
478					if node.ParentID == nil {
479						stat.RootSpans++
480					}
481					operation := operationStat(stat, node.Operation)
482					operation.SpanCount++
483					operation.SelfTimeNS += node.SelfTimeNS
484					operation.durations = append(operation.durations, node.DurationNS)
485					if node.Error {
486						operation.ErrorSpans++
487					}
488				}
489				byID := map[string]*TraceNode{}
490				for _, node := range trace.Spans {
491					byID[node.SpanID] = node
492				}
493				for _, node := range trace.Spans {
494					if node.ParentID == nil {
495						continue
496					}
497					parent := byID[*node.ParentID]
498					if parent == nil || parent.Service == node.Service {
499						continue
500					}
501					key := parent.Service + "\x00" + node.Service
502					edge := edges[key]
503					if edge == nil {
504						edge = &ServiceEdge{Caller: parent.Service, Callee: node.Service, durations: []int64{}}
505						edges[key] = edge
506					}
507					edge.CallCount++
508					edge.durations = append(edge.durations, node.DurationNS)
509					if node.Error {
510						edge.ErrorCount++
511					}
512				}
513			}
514			for _, stat := range services {
515				finalizeService(stat)
516				graph.Services = append(graph.Services, stat)
517			}
518			for _, edge := range edges {
519				finalizeEdge(edge)
520				graph.Edges = append(graph.Edges, edge)
521			}
522			sort.Slice(graph.Services, func(i, j int) bool { return graph.Services[i].Service < graph.Services[j].Service })
523			sort.Slice(graph.Edges, func(i, j int) bool {
524				if graph.Edges[i].Caller != graph.Edges[j].Caller {
525					return graph.Edges[i].Caller < graph.Edges[j].Caller
526				}
527				return graph.Edges[i].Callee < graph.Edges[j].Callee
528			})
529			finalizeStats(graph.Stats)
530			return graph, nil
531		})
532		if err != nil {
533			return nil, err
534		}
535		return value, nil
536	}
537	
538	func operationStat(service *ServiceStat, operation string) *OperationStat {
539		for _, stat := range service.Operations {
540			if stat.Operation == operation {
541				return stat
542			}
543		}
544		stat := &OperationStat{Operation: operation, durations: []int64{}}
545		service.Operations = append(service.Operations, stat)
546		return stat
547	}
548	
549	func finalizeService(stat *ServiceStat) {
550		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
551		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
552		stat.MeanDurationNS = mean(stat.durations)
553		stat.P50DurationNS = percentile(stat.durations, 50)
554		stat.P95DurationNS = percentile(stat.durations, 95)
555		stat.durations = nil
556		sort.Slice(stat.Operations, func(i, j int) bool { return stat.Operations[i].Operation < stat.Operations[j].Operation })
557		for _, operation := range stat.Operations {
558			finalizeOperation(operation)
559		}
560	}
561	
562	func finalizeOperation(stat *OperationStat) {
563		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
564		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
565		stat.MeanDurationNS = mean(stat.durations)
566		stat.P50DurationNS = percentile(stat.durations, 50)
567		stat.P95DurationNS = percentile(stat.durations, 95)
568		stat.durations = nil
569	}
570	
571	func finalizeEdge(edge *ServiceEdge) {
572		sort.Slice(edge.durations, func(i, j int) bool { return edge.durations[i] < edge.durations[j] })
573		edge.MinDurationNS, edge.MaxDurationNS = bounds(edge.durations)
574		edge.MeanDurationNS = mean(edge.durations)
575		edge.P50DurationNS = percentile(edge.durations, 50)
576		edge.P95DurationNS = percentile(edge.durations, 95)
577		edge.durations = nil
578	}
579	
580	func finalizeStats(stats *GraphStats) {
581		sort.Slice(stats.durations, func(i, j int) bool { return stats.durations[i] < stats.durations[j] })
582		stats.DurationNS, _ = bounds(stats.durations)
583		stats.MeanDurationNS = mean(stats.durations)
584		stats.P50DurationNS = percentile(stats.durations, 50)
585		stats.P95DurationNS = percentile(stats.durations, 95)
586		stats.durations = nil
587	}
588	
589	func bounds(sorted []int64) (int64, int64) {
590		if len(sorted) == 0 {
591			return 0, 0
592		}
593		return sorted[0], sorted[len(sorted)-1]
594	}
595	
596	func mean(sorted []int64) int64 {
597		if len(sorted) == 0 {
598			return 0
599		}
600		total := int64(0)
601		for _, value := range sorted {
602			total += value
603		}
604		return total / int64(len(sorted))
605	}
606	
607	// percentile uses the nearest-rank definition on already sorted input:
608	// index = ceil(p/100 * n) - 1. Input is never mutated.
609	func percentile(sorted []int64, p int) int64 {
610		if len(sorted) == 0 {
611			return 0
612		}
613		rank := (p*len(sorted) + 99) / 100
614		if rank < 1 {
615			rank = 1
616		}
617		if rank > len(sorted) {
618			rank = len(sorted)
619		}
620		return sorted[rank-1]
621	}
622	
623	func sortStrings(values []string) {
624		sort.Strings(values)
625	}
626

