24	func (s *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
25		status, response, err := s.dispatch(request, splitPath(request.URL.Path))
26		if err != nil {
27			writeError(writer, err)
28			return
29		}
30		writeJSON(writer, status, response)
31	}
