33	func (s *Server) dispatch(request *http.Request, parts []string) (int, any, error) {
34		method := request.Method
35		switch {
36		case method == http.MethodGet && len(parts) == 1 && parts[0] == "health":
37			if err := requireQuery(request); err != nil {
38				return 0, nil, err
39			}
40			return http.StatusOK, map[string]any{"status": "ok"}, nil
41	
42		case method == http.MethodPost && len(parts) == 1 && parts[0] == "spans":
43			body, err := readJSONBody(request)
44			if err != nil {
45				return 0, nil, err
46			}
47			response, err := s.service.IngestSpan(body, request.Header.Get("Idempotency-Key"))
48			return http.StatusCreated, response, err
49	
50		case method == http.MethodGet && len(parts) == 1 && parts[0] == "traces":
51			if err := requireQuery(request, "service", "limit"); err != nil {
52				return 0, nil, err
53			}
54			limit := 100
55			if raw := request.URL.Query().Get("limit"); raw != "" {
56				parsed, err := strconv.Atoi(raw)
57				if err != nil {
58					return 0, nil, ValidationError("limit must be an integer")
59				}
60				limit = parsed
61			}
62			response, err := s.service.ListTraces(strings.TrimSpace(request.URL.Query().Get("service")), limit)
63			return http.StatusOK, response, err
