245	type TraceSummary struct {
246		TraceID      string  `json:"trace_id"`
247		RootSpanID   *string `json:"root_span_id"`
248		RootService  *string `json:"root_service"`
249		StartTime    string  `json:"start_time"`
250		DurationNS   int64   `json:"duration_ns"`
251		SpanCount    int     `json:"span_count"`
252		ServiceCount int     `json:"service_count"`
253		ErrorSpans   int     `json:"error_spans"`
254		Complete     bool    `json:"complete"`
255		Valid        bool    `json:"valid"`
256	}
257	
258	// decodeObject strictly decodes one JSON object. Unknown fields, trailing
259	// content and non-object bodies are all rejected.
260	func decodeObject(body []byte, target any) error {
261		if len(bytes.TrimSpace(body)) == 0 {
262			return ValidationError("request body must be a JSON object")
263		}
264		decoder := json.NewDecoder(bytes.NewReader(body))
265		decoder.DisallowUnknownFields()
266		if err := decoder.Decode(target); err != nil {
267			return ValidationError("request body must be a JSON object with known fields: %s", err)
268		}
269		if err := decoder.Decode(new(any)); err != io.EOF {
270			return ValidationError("request body must contain exactly one JSON object")
271		}
272		return nil
273	}
274	
275	// formatTime renders one UTC instant in the canonical layout.
276	func formatTime(instant time.Time) string {
277		return instant.UTC().Format(idLayout)
278	}
279	
280	// parseTime accepts an RFC3339 timestamp with optional fractional seconds.
281	func parseTime(value string, field string) (time.Time, error) {
282		if strings.TrimSpace(value) == "" {
283			return time.Time{}, ValidationError("%s is required", field)
284		}
285		instant, err := time.Parse(time.RFC3339Nano, value)
286		if err != nil {
287			return time.Time{}, ValidationError("%s must be an RFC3339 timestamp", field)
288		}
289		return instant.UTC(), nil
290	}
291	
292	func validateIdentifier(value string, field string) (string, error) {
293		trimmed := strings.TrimSpace(value)
294		if trimmed == "" {
295			return "", ValidationError("%s is required", field)
296		}
297		if len(trimmed) > maxIdentifierLength {
298			return "", ValidationError("%s must be at most %d characters", field, maxIdentifierLength)
299		}
300		return trimmed, nil
301	}
302	
303	func validateText(value string, field string) (string, error) {
304		trimmed := strings.TrimSpace(value)
305		if trimmed == "" {
306			return "", ValidationError("%s is required", field)
307		}
308		if len(trimmed) > maxTextLength {
309			return "", ValidationError("%s must be at most %d characters", field, maxTextLength)
310		}
311		return trimmed, nil
312	}
313	
314	// validateSpanInput checks every rule that can be decided without looking at
315	// the other spans of the trace.
316	func validateSpanInput(input *SpanInput) (time.Time, error) {
317		if _, err := validateIdentifier(input.TraceID, "trace_id"); err != nil {
318			return time.Time{}, err
319		}
320		if _, err := validateIdentifier(input.SpanID, "span_id"); err != nil {
321			return time.Time{}, err
322		}
323		if input.ParentID != nil {
324			if strings.TrimSpace(*input.ParentID) == "" {
325				return time.Time{}, ValidationError("parent_id must be null or a non-empty identifier")
326			}
327		}
328		if _, err := validateText(input.Service, "service"); err != nil {
329			return time.Time{}, err
330		}
331		if _, err := validateText(input.Operation, "operation"); err != nil {
332			return time.Time{}, err
333		}
334		if !spanKinds[input.Kind] {
335			return time.Time{}, ValidationError("kind must be one of internal, server, client, producer or consumer")
336		}
337		if !spanStatuses[input.Status] {
338			return time.Time{}, ValidationError("status must be ok or error")
339		}
340		start, err := parseTime(input.StartTime, "start_time")
341		if err != nil {
342			return time.Time{}, err
343		}
344		if input.DurationNS < 0 {
345			return time.Time{}, ValidationError("duration_ns must be zero or positive")
346		}
347		if int64(start.UnixNano())+input.DurationNS > int64(maxTime.UnixNano()) {
348			return time.Time{}, ValidationError("start_time + duration_ns is beyond the supported range")
349		}
350		if len(input.Attributes) > maxAttributeCount {
351			return time.Time{}, ValidationError("attributes must contain at most %d entries", maxAttributeCount)
352		}
353		keys := make([]string, 0, len(input.Attributes))
354		for key := range input.Attributes {
355			keys = append(keys, key)
356		}
357		sort.Strings(keys)
358		for _, key := range keys {
359			if key == "" {
360				return time.Time{}, ValidationError("attribute keys must not be empty")
361			}
362			if len(key) > maxAttributeKey {
363				return time.Time{}, ValidationError("attribute key %s must be at most %d characters", key, maxAttributeKey)
364			}
365			if len(input.Attributes[key]) > maxAttributeValue {
366				return time.Time{}, ValidationError("attribute %s must be at most %d characters", key, maxAttributeValue)
367			}
368		}
369		if input.ParentID != nil && *input.ParentID == input.SpanID {
370			return time.Time{}, ValidationError("parent_id must not equal span_id on span %s", input.SpanID)
371		}
372		if input.ParentID == nil {
373			if input.SpanCount == nil {
374				return time.Time{}, ValidationError("span_count is required on a root span (parent_id null)")
375			}
376			if *input.SpanCount < 1 {
377				return time.Time{}, ValidationError("span_count must be at least 1")
378			}
379			if *input.SpanCount > maxSpanCount {
380				return time.Time{}, ValidationError("span_count must be at most %d", maxSpanCount)
381			}
382		} else if input.SpanCount != nil {
383			return time.Time{}, ValidationError("span_count is only allowed on a root span")
384		}
385		return start, nil
386	}
387	
388	// maxTime bounds start_time + duration_ns so that UnixNano arithmetic cannot
389	// overflow int64.
390	var maxTime = time.Date(2262, 4, 11, 23, 47, 16, 0, time.UTC)
391	
392	// lineOf resolves a span's trace id by walking parent links, which also detects
393	// a parent cycle and a parent that lives in another trace. A parent that has
394	// not been ingested yet simply ends the walk: every span of a trace carries the
395	// same trace id, so the input's own id is the answer.
396	func lineOf(spans map[string]*SpanInput, input *SpanInput) (string, error) {
397		seen := map[string]bool{input.SpanID: true}
398		current := input
399		for current.ParentID != nil {
400			parentID := *current.ParentID
401			if seen[parentID] {
402				return "", ConflictError("span %s has a cyclic parent_id chain", input.SpanID)
403			}
404			parent, found := spans[parentID]
405			if !found {
406				return input.TraceID, nil
407			}
408			seen[parentID] = true
409			if parent.TraceID != input.TraceID {
410				return "", ConflictError("span %s belongs to trace %s but its parent %s belongs to trace %s",
411					input.SpanID, input.TraceID, parentID, parent.TraceID)
412			}
413			current = parent
414		}
415		return input.TraceID, nil
416	}
417	
418	type treeBuilder struct {
419		spans      map[string]*SpanInput
420		children   map[string][]*SpanInput
421		roots      []*SpanInput
422		violations []Violation
423	}
424	
425	// assembleTrace rebuilds the span tree of one trace and derives every timing
426	// value. Violations are collected, never fatal, so a caller always sees why a
427	// trace is unusable.
428	func assembleTrace(traceID string, spans map[string]*SpanInput) *Trace {
429		trace := &Trace{
430			TraceID:    traceID,
431			SpanCount:  len(spans),
432			Valid:      true,
433			Violations: []Violation{},
434			Spans:      []*TraceNode{},
435		}
436		builder := &treeBuilder{
437			spans:    spans,
438			children: map[string][]*SpanInput{},
439		}
440		ids := make([]string, 0, len(spans))
441		for id := range spans {
442			ids = append(ids, id)
443		}
444		sort.Strings(ids)
445		for _, id := range ids {
446			span := spans[id]
447			if span.ParentID == nil {
448				builder.roots = append(builder.roots, span)
449				continue
450			}
451			if _, found := spans[*span.ParentID]; !found {
452				builder.violations = append(builder.violations, Violation{
453					Code:    "orphan_span",
454					TraceID: traceID,
455					SpanID:  span.SpanID,
456					Message: fmt.Sprintf("span %s references parent %s which is not part of trace %s",
457						span.SpanID, *span.ParentID, traceID),
458				})
459				continue
460			}
461			builder.children[*span.ParentID] = append(builder.children[*span.ParentID], span)
462		}
463		declared := 0
464		if len(builder.roots) == 1 && builder.roots[0].SpanCount != nil {
465			declared = *builder.roots[0].SpanCount
466		}
467		switch {
468		case len(builder.roots) == 1:
469		case len(builder.roots) == 0:
470			builder.violations = append(builder.violations, Violation{
471				Code:    "no_root_span",
472				TraceID: traceID,
473				SpanID:  "",
474				Message: fmt.Sprintf("trace %s has no span with a null parent_id", traceID),
475			})
476		default:
477			names := make([]string, 0, len(builder.roots))
478			for _, root := range builder.roots {
479				names = append(names, root.SpanID)
480			}
481			sort.Strings(names)
482			builder.violations = append(builder.violations, Violation{
483				Code:    "multiple_root_spans",
484				TraceID: traceID,
485				SpanID:  names[0],
486				Message: fmt.Sprintf("trace %s has %d root spans: %s", traceID, len(names), strings.Join(names, ", ")),
487			})
488		}
489		trace.RootSpanCount = declared
490		trace.Complete = len(builder.roots) == 1 && declared != 0 && declared == len(spans)
491		if declared != 0 && declared < len(spans) {
492			builder.violations = append(builder.violations, Violation{
493				Code:    "span_count_exceeded",
494				TraceID: traceID,
495				SpanID:  builder.roots[0].SpanID,
496				Message: fmt.Sprintf("trace %s declared span_count %d but %d spans were ingested",
497					traceID, declared, len(spans)),
498			})
499		}
500		if declared != 0 && declared > len(spans) {
501			builder.violations = append(builder.violations, Violation{
502				Code:    "trace_incomplete",
503				TraceID: traceID,
504				SpanID:  builder.roots[0].SpanID,
505				Message: fmt.Sprintf("trace %s declared span_count %d but only %d spans were ingested",
506					traceID, declared, len(spans)),
507			})
508		}
509	
510		// Every span that has no reachable root is still reported, as its own tree.
511		reachable := map[string]bool{}
512		for _, root := range builder.roots {
513			builder.markReachable(root, reachable)
514		}
515		for _, id := range ids {
516			if !reachable[id] && !builder.isOrphan(id) {
517				builder.violations = append(builder.violations, Violation{
518					Code:    "unreachable_span",
519					TraceID: traceID,
520					SpanID:  id,
521					Message: fmt.Sprintf("span %s is not reachable from a root span", id),
522				})
523			}
524		}
525	
526		sortedRoots := append([]*SpanInput{}, builder.roots...)
527		sort.Slice(sortedRoots, func(i, j int) bool {
528			left, _ := parseTime(sortedRoots[i].StartTime, "start_time")
529			right, _ := parseTime(sortedRoots[j].StartTime, "start_time")
530			if !left.Equal(right) {
531				return left.Before(right)
532			}
533			return sortedRoots[i].SpanID < sortedRoots[j].SpanID
534		})
535		for _, root := range sortedRoots {
536			start, _ := parseTime(root.StartTime, "start_time")
537			node := builder.buildNode(root, start, 0)
538			assignTiming(node)
539			trace.Spans = append(trace.Spans, flatten(node)...)
540			if trace.Root == nil {
541				trace.Root = node
542				trace.DurationNS = node.DurationNS
543			}
544		}
545		services := map[string]bool{}
546		for _, node := range trace.Spans {
547			collectServices(node, services)
548		}
549		trace.ServiceCount = len(services)
550		trace.ErrorSpans = countErrorSpans(trace.Spans)
551		trace.Valid = len(builder.violations) == 0
552		trace.Violations = builder.violations
553		sortViolations(trace.Violations)
554		return trace
555	}
556	
557	func (b *treeBuilder) isOrphan(id string) bool {
558		span := b.spans[id]
559		return span.ParentID != nil && b.spans[*span.ParentID] == nil
560	}
561	
562	func (b *treeBuilder) markReachable(span *SpanInput, seen map[string]bool) {
563		if seen[span.SpanID] {
564			return
565		}
566		seen[span.SpanID] = true
567		for _, child := range b.children[span.SpanID] {
568			b.markReachable(child, seen)
569		}
570	}
571	
572	// buildNode derives one node and everything below it. parentEnd is the
573	// exclusive end instant of the enclosing span; a child that overruns it is
574	// recorded as a violation and the node is still returned.
575	func (b *treeBuilder) buildNode(span *SpanInput, parentEnd time.Time, depth int) *TraceNode {
576		start, err := parseTime(span.StartTime, "start_time")
577		if err != nil {
578			start = time.Time{}
579		}
580		end := start.Add(time.Duration(span.DurationNS))
581		node := &TraceNode{
582			TraceID:      span.TraceID,
583			SpanID:       span.SpanID,
584			ParentID:     span.ParentID,
585			Service:      span.Service,
586			Operation:    span.Operation,
587			Kind:         span.Kind,
588			Status:       span.Status,
589			StartTime:    span.StartTime,
590			EndTime:      formatTime(end),
591			DurationNS:   span.DurationNS,
592			Depth:        depth,
593			Error:        span.Status == "error",
594			Attributes:   map[string]string{},
595			Children:     []*TraceNode{},
596			ErrorOrigins: []string{},
597		}
598		for key, value := range span.Attributes {
599			node.Attributes[key] = value
600		}
601		children := append([]*SpanInput{}, b.children[span.SpanID]...)
602		sort.Slice(children, func(i, j int) bool {
603			left, _ := parseTime(children[i].StartTime, "start_time")
604			right, _ := parseTime(children[j].StartTime, "start_time")
605			if !left.Equal(right) {
606				return left.Before(right)
607			}
608			return children[i].SpanID < children[j].SpanID
609		})
610		previousEnd := start
611		previousID := ""
612		for _, child := range children {
613			childStart, _ := parseTime(child.StartTime, "start_time")
614			childEnd := childStart.Add(time.Duration(child.DurationNS))
615			if childStart.Before(start) || childEnd.After(end) {
616				b.violations = append(b.violations, Violation{
617					Code:    "time_not_contained",
618					TraceID: span.TraceID,
619					SpanID:  child.SpanID,
620					Message: fmt.Sprintf("span %s runs from %s to %s which is not contained in parent %s from %s to %s",
621						child.SpanID, child.StartTime, formatTime(childEnd), span.SpanID, span.StartTime, formatTime(end)),
622				})
623			}
624			// Siblings must not overlap. Comparing each child against the furthest end
625			// seen so far catches an overlap with any earlier sibling, not only with
626			// the neighbour that starts just before it.
627			if previousID != "" && childStart.Before(previousEnd) {
628				b.violations = append(b.violations, Violation{
629					Code:    "sibling_overlap",
630					TraceID: span.TraceID,
631					SpanID:  previousID,
632					Message: fmt.Sprintf("span %s starts at %s before sibling %s ends at %s inside parent %s",
633						child.SpanID, child.StartTime, previousID, formatTime(previousEnd), span.SpanID),
634				})
635			}
636			if childEnd.After(previousEnd) {
637				previousEnd = childEnd
638				previousID = child.SpanID
639			}
640			node.Children = append(node.Children, b.buildNode(child, end, depth+1))
641		}
642		node.TotalDurationNS = span.DurationNS
643		for _, child := range node.Children {
644			if child.TotalDurationNS > span.DurationNS {
645				b.violations = append(b.violations, Violation{
646					Code:    "time_not_contained",
647					TraceID: span.TraceID,
648					SpanID:  child.SpanID,
649					Message: fmt.Sprintf("subtree of %s lasts %d but its parent %s only lasts %d",
650						child.SpanID, child.TotalDurationNS, span.SpanID, span.DurationNS),
651				})
652			}
653			if child.TotalDurationNS > node.TotalDurationNS {
654				node.TotalDurationNS = child.TotalDurationNS
655			}
656		}
657		origins := map[string]bool{}
658		if node.Error {
659			origins[span.SpanID] = true
660		}
661		for _, child := range node.Children {
662			for _, origin := range child.ErrorOrigins {
663				origins[origin] = true
664			}
665		}
666		for origin := range origins {
667			node.ErrorOrigins = append(node.ErrorOrigins, origin)
668		}
669		sort.Strings(node.ErrorOrigins)
670		node.ErrorOrigin = node.Error
671		// propagated marks a span whose subtree contains a failure that did not
672		// happen on the span itself. The declared status stays untouched: only the
673		// failing origin carries status "error".
674		node.Propagated = false
675		for _, origin := range node.ErrorOrigins {
676			if origin != node.SpanID {
677				node.Propagated = true
678				break
679			}
680		}
681		return node
682	}
683	
684	func collectServices(node *TraceNode, into map[string]bool) {
685		if into[node.Service] {
686			return
687		}
688		into[node.Service] = true
689		for _, child := range node.Children {
690			collectServices(child, into)
691		}
692	}
693	
694	// countErrorSpans counts failed spans in a flat span list. The list already
695	// contains every node once, so the nodes themselves are never walked again.
696	func countErrorSpans(nodes []*TraceNode) int {
697		total := 0
698		for _, node := range nodes {
699			if node.Error {
700				total++
701			}
702		}
703		return total
704	}
705	
706	func sortViolations(violations []Violation) {
707		sort.Slice(violations, func(i, j int) bool {
708			if violations[i].SpanID != violations[j].SpanID {
709				return violations[i].SpanID < violations[j].SpanID
710			}
711			return violations[i].Code < violations[j].Code
712		})
713	}
714	
715	// flatten walks the tree in pre-order and returns the nodes it contains.
716	func flatten(root *TraceNode) []*TraceNode {
717		if root == nil {
718			return nil
719		}
720		nodes := []*TraceNode{root}
721		for _, child := range root.Children {
722			nodes = append(nodes, flatten(child)...)
723		}
724		return nodes
725	}
