19	func newState() *State {
20		return &State{
21			Spans:       map[string]map[string]*SpanInput{},
22			Idempotency: map[string]*IdempotencyRecord{},
23		}
24	}
25	
26	func (s *State) repair() {
27		if s.Spans == nil {
28			s.Spans = map[string]map[string]*SpanInput{}
29		}
30		for traceID, spans := range s.Spans {
31			if spans == nil {
32				s.Spans[traceID] = map[string]*SpanInput{}
33			}
34		}
35		if s.Idempotency == nil {
36			s.Idempotency = map[string]*IdempotencyRecord{}
37		}
38	}
39	
40	// traceIDs returns the stored trace ids in lexicographic order.
41	func (s *State) traceIDs() []string {
42		ids := make([]string, 0, len(s.Spans))
43		for id := range s.Spans {
44			ids = append(ids, id)
45		}
46		sortStrings(ids)
47		return ids
48	}
49	
50	// Store owns the in-memory state and its file. Every mutation runs against a
51	// copy that is persisted first, so a failed write never changes the process
52	// state and no reader ever sees a half-applied transaction.
53	type Store struct {
54		path  string
55		mutex sync.Mutex
56		state *State
57	}
58	
59	// OpenStore loads the database at path, creating it on first write.
60	func OpenStore(path string) (*Store, error) {
61		if path == "" {
62			path = "tracepath.db"
63		}
64		state := newState()
65		contents, err := os.ReadFile(path)
66		switch {
67		case err == nil:
68			if err := json.Unmarshal(contents, state); err != nil {
69				return nil, InternalError("database %s is not readable JSON: %s", path, err)
70			}
71			state.repair()
72		case os.IsNotExist(err):
73		default:
74			return nil, InternalError("database %s could not be read: %s", path, err)
75		}
76		return &Store{path: path, state: state}, nil
77	}
78	
79	// Update runs mutate against a copy of the state and commits it on success.
80	func (s *Store) Update(mutate func(state *State) error) error {
